package store

// Differential / model-based property test. A fuzzer-generated byte stream is decoded
// into a random sequence of store operations and applied in lockstep to BOTH backends
// — the in-memory reference (MemStore) and the on-disk production store (FSStore). The
// reference is simple and obviously correct; the FS store is the complex one, so every
// observable result (version, error kind, ciphertext, head id, ChangedSince page +
// order, cursor, tombstone state, GC floor, quota) MUST match on both. A divergence is
// an FS bug. A cross-cutting invariant — QuotaBytes(account) equals the summed size of
// that account's live blobs — is checked on both backends at the end of each sequence.
//
// The seed corpus runs on every `go test`; `go test -fuzz=FuzzStoreDifferential`
// explores. No third-party property-testing dependency: Go's native fuzzer is the
// generator, keeping the server's minimal-dependency discipline.

import (
	"bytes"
	"testing"

	"github.com/myne-md/myne-server/internal/ids"
)

func sameMetas(a, b []SyncMeta) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] { // SyncMeta is all-comparable (arrays + ints)
			return false
		}
	}
	return true
}

func FuzzStoreDifferential(f *testing.F) {
	f.Add([]byte{})
	f.Add([]byte{0, 0, 0, 5, 1, 0, 0, 3, 2, 1})
	f.Add([]byte{3, 0, 0, 1, 3, 0, 7, 4, 0, 2})
	f.Add(bytes.Repeat([]byte{0, 1, 2, 3, 5, 6, 8, 9}, 6))

	f.Fuzz(func(t *testing.T, data []byte) {
		var mem BlobStore = NewMemStore()
		fsc, _ := newFS(t)
		var fs BlobStore = fsc

		acctOf := func(b byte) ids.AccountNumberHash { return acct(b % 3) }
		blobOf := func(b byte) ids.BlobID { return blob(b % 4) }
		devOf := func(b byte) ids.DeviceID { return deviceID(b % 3) }
		ctOf := func(b byte) []byte {
			if b%7 == 0 {
				return nil // exercise the empty-ciphertext edge
			}
			return bytes.Repeat([]byte{b}, int(b%17)+1)
		}

		pos := 0
		next := func() byte {
			if pos >= len(data) {
				return 0
			}
			b := data[pos]
			pos++
			return b
		}

		type abKey struct {
			a ids.AccountNumberHash
			b ids.BlobID
		}
		pairs := map[abKey]bool{}
		accounts := map[ids.AccountNumberHash]bool{}

		step := 0
		failVE := func(opn string, vm Version, em error, vf Version, ef error) {
			if (em == nil) != (ef == nil) {
				t.Fatalf("step %d %s: error divergence mem=%v fs=%v", step, opn, em, ef)
			}
			if em != nil && em.Error() != ef.Error() {
				t.Fatalf("step %d %s: error-kind divergence mem=%v fs=%v", step, opn, em, ef)
			}
			if vm != vf {
				t.Fatalf("step %d %s: version divergence mem=%d fs=%d", step, opn, vm, vf)
			}
		}

		for pos < len(data) && step < 128 {
			step++
			op := next() % 9
			a := acctOf(next())
			accounts[a] = true
			switch op {
			case 0: // PutBlob
				bl := blobOf(next())
				ct := ctOf(next())
				vm, em := mem.PutBlob(a, bl, ct)
				vf, ef := fs.PutBlob(a, bl, ct)
				failVE("put", vm, em, vf, ef)
				pairs[abKey{a, bl}] = true
			case 1: // PushBlob (CAS)
				bl := blobOf(next())
				base := Version(next() % 6)
				nz := nonce(next())
				ct := ctOf(next())
				vm, em := mem.PushBlob(a, bl, base, nz, ct)
				vf, ef := fs.PushBlob(a, bl, base, nz, ct)
				failVE("push", vm, em, vf, ef)
				pairs[abKey{a, bl}] = true
			case 2: // GetBlob + BlobVersion
				bl := blobOf(next())
				cm, vm, em := mem.GetBlob(a, bl)
				cf, vf, ef := fs.GetBlob(a, bl)
				failVE("get", vm, em, vf, ef)
				if !bytes.Equal(cm, cf) {
					t.Fatalf("step %d get: ciphertext divergence", step)
				}
				bvm, bem := mem.BlobVersion(a, bl)
				bvf, bef := fs.BlobVersion(a, bl)
				failVE("blobversion", bvm, bem, bvf, bef)
			case 3: // AdvanceHead (genesis-zero or current head)
				var prev [HeadIDLen]byte
				if next()%2 == 0 {
					if _, hid, err := mem.GetHead(a); err == nil {
						prev = hid
					}
				}
				rec := ctOf(next())
				hm, em := mem.AdvanceHead(a, prev, rec)
				hf, ef := fs.AdvanceHead(a, prev, rec)
				if (em == nil) != (ef == nil) {
					t.Fatalf("step %d advancehead: error divergence mem=%v fs=%v", step, em, ef)
				}
				if em == nil && hm != hf {
					t.Fatalf("step %d advancehead: head-id divergence", step)
				}
			case 4: // GetHead
				rm, hm, em := mem.GetHead(a)
				rf, hf, ef := fs.GetHead(a)
				if (em == nil) != (ef == nil) {
					t.Fatalf("step %d gethead: error divergence", step)
				}
				if em == nil && (!bytes.Equal(rm, rf) || hm != hf) {
					t.Fatalf("step %d gethead: record/id divergence", step)
				}
			case 5: // AckCursor + DeviceCursor
				d := devOf(next())
				p := uint64(next())
				mem.AckCursor(a, d, p)
				fs.AckCursor(a, d, p)
				if mem.DeviceCursor(a, d) != fs.DeviceCursor(a, d) {
					t.Fatalf("step %d cursor: divergence mem=%d fs=%d", step, mem.DeviceCursor(a, d), fs.DeviceCursor(a, d))
				}
			case 6: // ChangedSince
				cur := uint64(next() % 8)
				lim := int(next() % 6)
				mm, mc := mem.ChangedSince(a, cur, lim)
				fm, fc := fs.ChangedSince(a, cur, lim)
				if mc != fc {
					t.Fatalf("step %d changedsince: cursor divergence mem=%d fs=%d", step, mc, fc)
				}
				if !sameMetas(mm, fm) {
					t.Fatalf("step %d changedsince: metas divergence mem=%+v fs=%+v", step, mm, fm)
				}
			case 7: // SetTombstone + Tombstone + TombstoneRecord
				bl := blobOf(next())
				fv := Version(next() % 6)
				em := mem.SetTombstone(a, bl, fv)
				ef := fs.SetTombstone(a, bl, fv)
				if (em == nil) != (ef == nil) {
					t.Fatalf("step %d settombstone: error divergence", step)
				}
				tvm, okm := mem.Tombstone(a, bl)
				tvf, okf := fs.Tombstone(a, bl)
				if okm != okf || tvm != tvf {
					t.Fatalf("step %d tombstone: divergence mem=(%d,%t) fs=(%d,%t)", step, tvm, okm, tvf, okf)
				}
				rvm, rsm, rrm, rokm := mem.TombstoneRecord(a, bl)
				rvf, rsf, rrf, rokf := fs.TombstoneRecord(a, bl)
				if rokm != rokf || rvm != rvf || rsm != rsf || rrm != rrf {
					t.Fatalf("step %d tombstonerecord: divergence", step)
				}
			case 8: // ReclaimTombstone + GCFloor + QuotaBytes
				bl := blobOf(next())
				em := mem.ReclaimTombstone(a, bl)
				ef := fs.ReclaimTombstone(a, bl)
				if (em == nil) != (ef == nil) {
					t.Fatalf("step %d reclaim: error divergence mem=%v fs=%v", step, em, ef)
				}
				if mem.GCFloor(a) != fs.GCFloor(a) {
					t.Fatalf("step %d gcfloor: divergence mem=%d fs=%d", step, mem.GCFloor(a), fs.GCFloor(a))
				}
				if mem.QuotaBytes(a) != fs.QuotaBytes(a) {
					t.Fatalf("step %d reclaim: quota divergence mem=%d fs=%d", step, mem.QuotaBytes(a), fs.QuotaBytes(a))
				}
			}
		}

		// End-of-sequence invariant on BOTH backends: QuotaBytes equals the summed size
		// of an account's live (non-reclaimed) blobs.
		for _, s := range []BlobStore{mem, fs} {
			sums := map[ids.AccountNumberHash]uint64{}
			for k := range pairs {
				if ct, _, err := s.GetBlob(k.a, k.b); err == nil {
					sums[k.a] += uint64(len(ct))
				}
			}
			for a := range accounts {
				if got := s.QuotaBytes(a); got != sums[a] {
					t.Fatalf("quota invariant: QuotaBytes(%#x..)=%d, sum of live blobs=%d", a[0], got, sums[a])
				}
			}
		}
	})
}
